import type { AvatarPackage } from '@naavos/schema';

import { renderContext } from '../context.js';
import type { FileMap } from '../index.js';

export function openclawAdapter(pkg: AvatarPackage): FileMap {
  return new Map([
    [
      'AGENTS.md',
      '# Agent Configuration\n\n> Generated by NAAvOS. Recompile to update.\n\n' +
        renderContext(pkg),
    ],
  ]);
}
